on whatsoever. - You are ABSOLUTELY FORBIDDEN from adding any introductory text, concluding remarks, explanations, parentheses, footnotes, or any text that is not a bullet point. - Your response MUST consist EXCLUSIVELY of raw bullet points starting with “- “ and containing only the description of one individual error. - There must be NO text before the first bullet point. - There must be NO text after the last bullet point. - The response must begin immediately with the first “- “ bullet point and end with the last bullet point. - You MUST continue listing every single identifiable issue in the entire codebase individually until you have listed absolutely every one. - Even if the list would theoretically become thousands of lines long, you must list every single instance separately in its own bullet point.  Begin the audit immediately with the first bullet point. Do not write anything else. No introductions. No explanations. Only bullet points. minden egyes karaktert VALÓBAN elolvasol és feldolgozol elsőtől az utolsóig és az ÖSSZES hibát listába írod a teljesség igényével! válaszodban szeretném ha csak listába írnád a dolgokat amiket keresek, minden más nélkül.   még ha 80000 hiba is van akkor MINDET TENYLEGESEN  megirod kivetel nelkul! 

const std = @import("std");
const config = @import("config.zig");
const agent = @import("agent.zig");
const llm = @import("llm.zig");
const tools = @import("tools.zig");
const planner = @import("planner.zig");

const MAX_CONCURRENT_CONNECTIONS: usize = 1000;
const REQUEST_BUFFER_SIZE: usize = 64 * 1024;

pub const Server = struct {
    allocator: std.mem.Allocator,
    cfg: config.Config,
    stream_server: std.net.StreamServer,
    active_connections: std.atomic.Atomic(usize),

    pub fn init(allocator: std.mem.Allocator, cfg: config.Config) !Server {
        var stream_server = std.net.StreamServer.init(.{
            .reuse_address = true,
        });

        const address = std.net.Address.initIp4(.{ 0, 0, 0, 0 }, cfg.port);
        stream_server.listen(address) catch |err| {
            std.log.err("Failed to listen: {}", .{err});
            return err;
        };

        return Server{
            .allocator = allocator,
            .cfg = cfg,
            .stream_server = stream_server,
            .active_connections = std.atomic.Atomic(usize).init(0),
        };
    }

    pub fn deinit(self: *Server) void {
        self.stream_server.deinit();
    }

    pub fn listen(self: *Server) !void {
        std.log.info("Server listening on 0.0.0.0:{d}", .{self.cfg.port});

        while (true) {
            const connection = self.stream_server.accept() catch |err| {
                std.log.err("Accept error: {}", .{err});
                continue;
            };

            const current = self.active_connections.load(.Monotonic);
            if (current >= MAX_CONCURRENT_CONNECTIONS) {
                std.log.warn("Too many connections ({d}), rejecting", .{current});
                connection.stream.close();
                continue;
            }

            _ = self.active_connections.fetchAdd(1, .Monotonic);

            const thread = std.Thread.spawn(.{}, handleConnectionWrapper, .{ self, connection }) catch |err| {
                std.log.err("Thread spawn error: {}", .{err});
                _ = self.active_connections.fetchSub(1, .Monotonic);
                connection.stream.close();
                continue;
            };
            thread.detach();
        }
    }

    fn handleConnectionWrapper(self: *Server, connection: std.net.StreamServer.Connection) void {
        defer {
            _ = self.active_connections.fetchSub(1, .Monotonic);
        }
        self.handleConnection(connection);
    }

    fn handleConnection(self: *Server, connection: std.net.StreamServer.Connection) void {
        defer connection.stream.close();

        var buf: [REQUEST_BUFFER_SIZE]u8 = undefined;
        var total_read: usize = 0;
        var header_end: ?usize = null;

        while (total_read < REQUEST_BUFFER_SIZE) {
            const bytes_read = connection.stream.read(buf[total_read..]) catch |err| {
                std.log.err("Read error: {}", .{err});
                return;
            };

            if (bytes_read == 0) break;
            total_read += bytes_read;

            if (header_end == null) {
                if (std.mem.indexOf(u8, buf[0..total_read], "\r\n\r\n")) |idx| {
                    header_end = idx + 4;

                    const header_section = buf[0..idx];
                    var content_length: usize = 0;

                    var lines = std.mem.splitSequence(u8, header_section, "\r\n");
                    while (lines.next()) |line| {
                        if (std.ascii.startsWithIgnoreCase(line, "content-length:")) {
                            const value = std.mem.trim(u8, line[15..], " ");
                            content_length = std.fmt.parseUnsigned(usize, value, 10) catch 0;
                            break;
                        }
                    }

                    const expected_total = header_end.? + content_length;
                    if (total_read >= expected_total or content_length == 0) break;
                    if (expected_total > REQUEST_BUFFER_SIZE) break;
                }
            } else {
                break;
            }
        }

        if (total_read == 0) return;

        const request = buf[0..total_read];
        self.handleRequest(connection.stream, request) catch |err| {
            std.log.err("Handle request error: {}", .{err});
        };
    }

    fn handleRequest(self: *Server, stream: std.net.Stream, request: []const u8) !void {
        var lines = std.mem.split(u8, request, "\r\n");
        const request_line = lines.next() orelse return;

        var parts = std.mem.split(u8, request_line, " ");
        const method = parts.next() orelse return;
        const path = parts.next() orelse return;

        var headers = std.StringHashMap([]const u8).init(self.allocator);
        defer headers.deinit();

        while (lines.next()) |line| {
            if (line.len == 0) break;
            if (std.mem.indexOf(u8, line, ": ")) |idx| {
                try headers.put(line[0..idx], line[idx + 2 ..]);
            }
        }

        var body: []const u8 = "";
        if (std.mem.indexOf(u8, request, "\r\n\r\n")) |idx| {
            body = request[idx + 4 ..];
        }

        const is_public = std.mem.eql(u8, path, "/") or
            std.mem.eql(u8, path, "/index.html") or
            std.mem.eql(u8, path, "/style.css") or
            std.mem.eql(u8, path, "/app.js") or
            std.mem.eql(u8, path, "/favicon.ico") or
            std.mem.eql(u8, path, "/health") or
            std.mem.eql(u8, path, "/api/models") or
            std.mem.eql(u8, path, "/api/tools") or
            std.mem.eql(u8, path, "/api/status") or
            std.mem.eql(u8, path, "/api/auth/login") or
            std.mem.eql(u8, path, "/api/auth/register") or
            std.mem.eql(u8, method, "OPTIONS");

        if (!is_public and !self.checkAuth(&headers)) {
            try self.sendResponse(stream, 401, "{\"error\":\"Unauthorized\"}");
            return;
        }

        if (std.mem.eql(u8, method, "GET")) {
            if (std.mem.eql(u8, path, "/") or std.mem.eql(u8, path, "/index.html")) {
                try self.serveStaticFile(stream, "public/index.html", "text/html");
            } else if (std.mem.eql(u8, path, "/style.css")) {
                try self.serveStaticFile(stream, "public/style.css", "text/css");
            } else if (std.mem.eql(u8, path, "/app.js")) {
                try self.serveStaticFile(stream, "public/app.js", "application/javascript");
            } else if (std.mem.eql(u8, path, "/favicon.ico")) {
                try self.serveStaticFile(stream, "public/favicon.ico", "image/x-icon");
            } else if (std.mem.eql(u8, path, "/health")) {
                try self.sendResponse(stream, 200, "{\"status\":\"ok\",\"service\":\"clouddev-agent\",\"version\":\"1.0.0\"}");
            } else if (std.mem.eql(u8, path, "/api/models")) {
                try self.handleGetModels(stream);
            } else if (std.mem.eql(u8, path, "/api/tools")) {
                try self.handleGetTools(stream);
            } else if (std.mem.eql(u8, path, "/api/status")) {
                try self.handleStatus(stream);
            } else if (std.mem.startsWith(u8, path, "/api/projects")) {
                try self.handleProjectsGet(stream, path);
            } else if (std.mem.startsWith(u8, path, "/api/files")) {
                try self.handleFilesGet(stream, path);
            } else if (std.mem.startsWith(u8, path, "/api/agent/")) {
                try self.handleAgentGet(stream, path);
            } else {
                try self.sendResponse(stream, 404, "{\"error\":\"Not found\"}");
            }
        } else if (std.mem.eql(u8, method, "POST")) {
            if (std.mem.eql(u8, path, "/api/auth/login")) {
                try self.handleAuthLogin(stream, body);
            } else if (std.mem.eql(u8, path, "/api/auth/register")) {
                try self.handleAuthRegister(stream, body);
            } else if (std.mem.eql(u8, path, "/api/chat")) {
                try self.handleChat(stream, body);
            } else if (std.mem.eql(u8, path, "/api/plan")) {
                try self.handlePlan(stream, body);
            } else if (std.mem.eql(u8, path, "/api/execute")) {
                try self.handleExecute(stream, body);
            } else if (std.mem.eql(u8, path, "/api/tool")) {
                try self.handleTool(stream, body);
            } else if (std.mem.eql(u8, path, "/api/agent/start")) {
                try self.handleAgentStart(stream, body);
            } else if (std.mem.eql(u8, path, "/api/checkpoint")) {
                try self.handleCheckpoint(stream, body);
            } else if (std.mem.eql(u8, path, "/api/rollback")) {
                try self.handleRollback(stream, body);
            } else if (std.mem.eql(u8, path, "/api/projects")) {
                try self.handleProjectCreate(stream, body);
            } else if (std.mem.eql(u8, path, "/api/files")) {
                try self.handleFileWrite(stream, body);
            } else if (std.mem.eql(u8, path, "/api/search")) {
                try self.handleSearch(stream, body);
            } else if (std.mem.eql(u8, path, "/api/agent/pause")) {
                try self.handleAgentPause(stream, body);
            } else if (std.mem.eql(u8, path, "/api/agent/resume")) {
                try self.handleAgentResume(stream, body);
            } else if (std.mem.eql(u8, path, "/api/agent/cancel")) {
                try self.handleAgentCancel(stream, body);
            } else {
                try self.sendResponse(stream, 404, "{\"error\":\"Not found\"}");
            }
        } else if (std.mem.eql(u8, method, "OPTIONS")) {
            try self.sendCorsResponse(stream);
        } else {
            try self.sendResponse(stream, 405, "{\"error\":\"Method not allowed\"}");
        }
    }

    fn checkAuth(self: *Server, headers: *std.StringHashMap([]const u8)) bool {
        if (self.cfg.internal_api_key.len == 0) {
            std.log.warn("No API key configured - authentication disabled", .{});
            return true;
        }

        if (headers.get("X-Internal-API-Key")) |key| {
            if (std.mem.eql(u8, key, self.cfg.internal_api_key)) return true;
        }
        if (headers.get("Authorization")) |auth| {
            if (std.mem.startsWith(u8, auth, "Bearer ")) {
                if (std.mem.eql(u8, auth[7..], self.cfg.internal_api_key)) return true;
            }
        }
        return false;
    }

    fn handleGetModels(self: *Server, stream: std.net.Stream) !void {
        const response =
            \\{"models":[
            \\{"id":"grok-4-fast","provider":"xai","description":"Grok 4.1 Fast Reasoning - High performance reasoning model"},
            \\{"id":"grok-4","provider":"xai","description":"Grok 4 - Full capability model"},
            \\{"id":"zai-glm-4.6","provider":"cerebras","description":"Cerebras GLM 4.6 - Ultra fast inference"},
            \\{"id":"llama-3.3-70b","provider":"cerebras","description":"Llama 3.3 70B on Cerebras"},
            \\{"id":"qwen-3-32b","provider":"cerebras","description":"Qwen 3 32B on Cerebras"}
            \\]}
        ;
        try self.sendResponse(stream, 200, response);
    }

    fn handleGetTools(self: *Server, stream: std.net.Stream) !void {
        const response = tools.getToolsJson();
        try self.sendResponse(stream, 200, response);
    }

    fn handleChat(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const message = if (root.get("message")) |m| m.string else "";
        const model = if (root.get("model")) |m| m.string else self.cfg.default_model;
        const mode = if (root.get("mode")) |m| m.string else "chat";

        if (message.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Missing message\"}");
            return;
        }

        const response = llm.chatCompletion(self.allocator, &self.cfg, model, message, mode) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(response);

        var response_json = std.ArrayList(u8).init(self.allocator);
        defer response_json.deinit();

        try response_json.appendSlice("{\"content\":");
        var writer = response_json.writer();
        try std.json.stringify(response, .{}, writer);
        try response_json.appendSlice(",\"model\":\"");
        try response_json.appendSlice(model);
        try response_json.appendSlice("\",\"mode\":\"");
        try response_json.appendSlice(mode);
        try response_json.appendSlice("\"}");

        try self.sendResponse(stream, 200, response_json.items);
    }

    fn handlePlan(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const prompt = if (root.get("prompt")) |p| p.string else "";

        if (prompt.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Missing prompt\"}");
            return;
        }

        const plan = planner.createPlan(self.allocator, &self.cfg, prompt) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(plan);

        try self.sendResponse(stream, 200, plan);
    }

    fn handleExecute(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const plan_id = if (root.get("plan_id")) |p| p.string else "";

        const result = agent.executePlan(self.allocator, &self.cfg, plan_id) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);

        try self.sendResponse(stream, 200, result);
    }

    fn handleTool(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const tool_name = if (root.get("tool")) |t| t.string else "";
        const args_val = root.get("args");

        if (tool_name.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Missing tool name\"}");
            return;
        }

        const result = tools.executeToolFromValue(self.allocator, tool_name, args_val) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);

        try self.sendResponse(stream, 200, result);
    }

    fn handleAgentStart(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const prompt = if (root.get("prompt")) |p| p.string else "";
        const autonomy = if (root.get("autonomy_level")) |a| a.string else "medium";

        if (prompt.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Missing prompt\"}");
            return;
        }

        const result = agent.startAgent(self.allocator, &self.cfg, prompt, autonomy) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);

        try self.sendResponse(stream, 200, result);
    }

    fn handleCheckpoint(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const name = if (root.get("name")) |n| n.string else "checkpoint";
        const description = if (root.get("description")) |d| d.string else "";

        const result = tools.createCheckpoint(self.allocator, name, description) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);

        try self.sendResponse(stream, 200, result);
    }

    fn handleRollback(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Invalid JSON\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const checkpoint_id = if (root.get("checkpoint_id")) |c| c.string else "";

        if (checkpoint_id.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Missing checkpoint_id\"}");
            return;
        }

        const result = tools.rollbackToCheckpoint(self.allocator, checkpoint_id) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);

        try self.sendResponse(stream, 200, result);
    }

    fn handleStatus(self: *Server, stream: std.net.Stream) !void {
        const timestamp = std.time.timestamp();
        const active = self.active_connections.load(.Monotonic);
        const response = std.fmt.allocPrint(
            self.allocator,
            "{{\"status\":\"running\",\"uptime\":{d},\"version\":\"1.0.0\",\"language\":\"zig-0.11\",\"binary_size_mb\":3.4,\"databases\":{{\"cockroachdb\":\"connected\",\"scylladb\":\"pending\"}},\"models\":5,\"tools\":14,\"active_connections\":{d},\"max_connections\":{d}}}",
            .{ timestamp, active, MAX_CONCURRENT_CONNECTIONS },
        ) catch "{\"error\":\"Failed to format status\"}";
        defer self.allocator.free(response);
        try self.sendResponse(stream, 200, response);
    }

    fn handleProjectsGet(self: *Server, stream: std.net.Stream, path: []const u8) !void {
        _ = path;
        try self.sendResponse(stream, 200, "{\"projects\":[],\"total\":0}");
    }

    fn handleFilesGet(self: *Server, stream: std.net.Stream, path: []const u8) !void {
        if (std.mem.indexOf(u8, path, "?path=")) |idx| {
            const file_path = path[idx + 6 ..];
            var args_obj = std.json.ObjectMap.init(self.allocator);
            defer args_obj.deinit();
            try args_obj.put("path", .{ .string = file_path });
            const result = tools.executeToolFromValue(self.allocator, "file_read", .{ .object = args_obj }) catch {
                try self.sendResponse(stream, 500, "{\"error\":\"Failed to read file\"}");
                return;
            };
            defer self.allocator.free(result);
            try self.sendResponse(stream, 200, result);
        } else {
            var args_obj = std.json.ObjectMap.init(self.allocator);
            defer args_obj.deinit();
            try args_obj.put("path", .{ .string = "." });
            const result = tools.executeToolFromValue(self.allocator, "file_list", .{ .object = args_obj }) catch {
                try self.sendResponse(stream, 500, "{\"error\":\"Failed to list files\"}");
                return;
            };
            defer self.allocator.free(result);
            try self.sendResponse(stream, 200, result);
        }
    }

    fn handleAgentGet(self: *Server, stream: std.net.Stream, path: []const u8) !void {
        if (std.mem.indexOf(u8, path, "/api/agent/status/")) |idx| {
            const agent_id = path[idx + 18 ..];
            const result = agent.getAgentStatus(self.allocator, agent_id) catch {
                try self.sendResponse(stream, 500, "{\"error\":\"Failed to get agent status\"}");
                return;
            };
            defer self.allocator.free(result);
            try self.sendResponse(stream, 200, result);
        } else {
            try self.sendResponse(stream, 200, "{\"agents\":[]}");
        }
    }

    fn hashPassword(allocator: std.mem.Allocator, password: []const u8, salt: []const u8) ![]u8 {
        var combined = std.ArrayList(u8).init(allocator);
        defer combined.deinit();
        try combined.appendSlice(password);
        try combined.appendSlice(salt);
        const hash = std.hash.Wyhash.hash(0, combined.items);
        return try std.fmt.allocPrint(allocator, "{x:0>16}", .{hash});
    }

    fn generateToken(allocator: std.mem.Allocator, user_id: []const u8) ![]u8 {
        var random_bytes: [32]u8 = undefined;
        std.os.getrandom(&random_bytes) catch return error.NoSecureRandom;
        const rand_high = std.mem.readIntNative(u128, random_bytes[0..16]);
        const rand_low = std.mem.readIntNative(u128, random_bytes[16..32]);
        return try std.fmt.allocPrint(allocator, "nf_{x:0>32}{x:0>32}_{s}", .{ rand_high, rand_low, user_id });
    }

    fn handleAuthLogin(self: *Server, stream: std.net.Stream, body: []const u8) !void {
