    fn hashPassword(allocator: std.mem.Allocator, password: []const u8, salt: []const u8) ![]u8 {
        var combined = std.ArrayList(u8).init(allocator);
        defer combined.deinit();
        try combined.appendSlice(password);
        try combined.appendSlice(salt);
        const hash = std.hash.Wyhash.hash(0, combined.items);
        return try std.fmt.allocPrint(allocator, "{x:0>16}", .{hash});
    }

    fn generateToken(allocator: std.mem.Allocator, user_id: []const u8) ![]u8 {
        var random_bytes: [32]u8 = undefined;
        std.os.getrandom(&random_bytes) catch return error.NoSecureRandom;
        const rand_high = std.mem.readIntNative(u128, random_bytes[0..16]);
        const rand_low = std.mem.readIntNative(u128, random_bytes[16..32]);
        return try std.fmt.allocPrint(allocator, "nf_{x:0>32}{x:0>32}_{s}", .{ rand_high, rand_low, user_id });
    }

    fn handleAuthLogin(self: *Server, stream: std.net.Stream, body: []const u8) !void {
        const parsed = std.json.parseFromSlice(std.json.Value, self.allocator, body, .{}) catch {
            try self.sendResponse(stream, 400, "{\"error\":\"Érvénytelen JSON formátum\"}");
            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const email = if (root.get("email")) |e| e.string else "";
        const password = if (root.get("password")) |p| p.string else "";

        if (email.len == 0 or password.len == 0) {
            try self.sendResponse(stream, 400, "{\"error\":\"Email és jelszó megadása kötelező\"}");
            return;
        }

        if (email.len > 255 or password.len > 128) {
            try self.sendResponse(stream, 400, "{\"error\":\"Túl hosszú bemenet\"}");
            return;
        }

        const timestamp = std.time.timestamp();
        const user_id_hash = std.hash.Wyhash.hash(0, email);
        const user_id = std.fmt.allocPrint(self.allocator, "u_{x:0>12}", .{user_id_hash}) catch {
            try self.sendResponse(stream, 500, "{\"error\":\"Belső hiba\"}");
            return;
        };
        defer self.allocator.free(user_id);

        const token = generateToken(self.allocator, user_id) catch {
            try self.sendResponse(stream, 500, "{\"error\":\"Token generálási hiba\"}");
            return;
        };
        defer self.allocator.free(token);

        var name_buf: [256]u8 = undefined;
        const at_idx = std.mem.indexOf(u8, email, "@") orelse email.len;
        const local_part = email[0..at_idx];
        const display_name = std.fmt.bufPrint(&name_buf, "{s}", .{local_part}) catch "Felhasználó";

        var escaped_email = std.ArrayList(u8).init(self.allocator);
        defer escaped_email.deinit();
        for (email) |c| {
            if (c == '"' or c == '\\') {
                try escaped_email.append('\\');
            }
            try escaped_email.append(c);
        }

        var escaped_name = std.ArrayList(u8).init(self.allocator);
        defer escaped_name.deinit();
        for (display_name) |c| {
            if (c == '"' or c == '\\') {
                try escaped_name.append('\\');
            }
            try escaped_name.append(c);
        }

        const response = std.fmt.allocPrint(
            self.allocator,
            "{{\"user\":{{\"id\":\"{s}\",\"email\":\"{s}\",\"full_name\":\"{s}\",\"credits\":10000,\"plan\":\"pro\",\"created_at\":{d}}},\"token\":\"{s}\"}}",
            .{ user_id, escaped_email.items, escaped_name.items, timestamp, token },
        ) catch {
            try self.sendResponse(stream, 500, "{\"error\":\"Belső szerverhiba\"}");
            return;
        };
        defer self.allocator.free(response);
        try self.sendResponse(stream, 200, response);
    }

