            return;
        };
        defer parsed.deinit();

        const root = parsed.value.object;
        const agent_id = if (root.get("agent_id")) |a| a.string else "";

        const result = agent.cancelAgent(self.allocator, agent_id) catch |err| {
            const err_msg = std.fmt.allocPrint(self.allocator, "{{\"error\":\"{}\"}}", .{err}) catch "{\"error\":\"Unknown error\"}";
            try self.sendResponse(stream, 500, err_msg);
            return;
        };
        defer self.allocator.free(result);
        try self.sendResponse(stream, 200, result);
    }

    fn sendResponse(self: *Server, stream: std.net.Stream, status: u16, body: []const u8) !void {
        const status_text = switch (status) {
            200 => "OK",
            400 => "Bad Request",
            401 => "Unauthorized",
            404 => "Not Found",
            405 => "Method Not Allowed",
            500 => "Internal Server Error",
            else => "Unknown",
        };

        var response = std.ArrayList(u8).init(self.allocator);
        defer response.deinit();

        try response.writer().print(
            "HTTP/1.1 {d} {s}\r\n" ++
                "Content-Type: application/json\r\n" ++
                "Content-Length: {d}\r\n" ++
                "Access-Control-Allow-Origin: *\r\n" ++
                "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n" ++
                "Access-Control-Allow-Headers: Content-Type, Authorization, X-Internal-API-Key\r\n" ++
                "Cache-Control: no-cache, no-store, must-revalidate\r\n" ++
                "Connection: close\r\n" ++
                "\r\n",
            .{ status, status_text, body.len },
        );
        try response.appendSlice(body);

        _ = stream.write(response.items) catch |err| {
            std.log.warn("response write error: {}", .{err});
        };
    }

